-- Catalogue en natures (familles) et variétés (documents délivrables), comme la version 1 : durée de validité,
-- mots-clés, pièces à fournir, rubriques du formulaire, lien entre un original et ses copies. On y reprend les
-- 36 natures de la version 1 et les documents du modèle Nature / Variété.

CREATE TABLE nature (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(40)  NOT NULL UNIQUE,
    libelle     VARCHAR(100) NOT NULL,
    description VARCHAR(500),
    ordre       INTEGER      NOT NULL DEFAULT 0,
    active      BOOLEAN      NOT NULL DEFAULT TRUE
);

ALTER TABLE type_document ADD COLUMN nature_id BIGINT REFERENCES nature (id);
ALTER TABLE type_document ADD COLUMN type_mention VARCHAR(30);
ALTER TABLE type_document ADD COLUMN champs VARCHAR(200);
ALTER TABLE type_document ADD COLUMN duree_validite_jours INTEGER;
ALTER TABLE type_document ADD COLUMN mots_cles VARCHAR(255);
ALTER TABLE type_document ADD COLUMN pieces_a_fournir VARCHAR(1000);
ALTER TABLE type_document ADD COLUMN est_original BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE type_document ADD COLUMN copie_de_id BIGINT REFERENCES type_document (id);
ALTER TABLE type_document ALTER COLUMN code SET DATA TYPE VARCHAR(60);

ALTER TABLE motif ADD COLUMN pieces_requises VARCHAR(500);
ALTER TABLE motif ADD COLUMN type_document_id BIGINT REFERENCES type_document (id);
ALTER TABLE motif DROP CONSTRAINT IF EXISTS motif_libelle_key;

ALTER TABLE demande ADD COLUMN complements VARCHAR(4000);
ALTER TABLE demande ADD COLUMN duree_validite_jours INTEGER;
