-- Documents ajoutés par l'administrateur avant cette version : rangés selon leur type d'acte
UPDATE type_document SET nature_id = (SELECT id FROM nature WHERE code = type_document.type_acte) WHERE nature_id IS NULL;
ALTER TABLE type_document ALTER COLUMN nature_id SET NOT NULL;

